def _load_the_first_expected(model_type: str) -> Any:
    """Load the first recorded example of the ``model_type``."""
    paths = sorted(
        (
            tests.common.TEST_DATA_DIR
            / "Json"
            / "Expected"
            / model_type
        ).glob("**/*.json")
    )

    assert len(paths) > 0, (
        f"Expected at least one recorded example of {model_type}, but got none"
    )

    with paths[0].open("rt") as fid:
        return json.load(fid)


def _paths_and_causes(
        errors: Iterable[our_reporting.Error]
) -> List[Tuple[str, str]]:
    return [(str(error.path), error.cause) for error in errors]


class TestPredicateAndMessages(unittest.TestCase):
    def test_is_safe_integer(self) -> None:
        for value in [0, 2 ** 53 - 1, -(2 ** 53 - 1)]:
            self.assertTrue(our_common.is_safe_integer(value), f"for {value}")

        for value in [2 ** 53, -(2 ** 53), 10 ** 400]:
            self.assertFalse(our_common.is_safe_integer(value), f"for {value}")

    def test_unsafe_integer_message(self) -> None:
        self.assertEqual(
            "Expected an integer, but got 9007199254740992, "
            "which is outside the safe integer range [-2^53 + 1, 2^53 - 1]",
            our_common.unsafe_integer_message(2 ** 53)
        )


